{
  "packet_id": "H6-T02-1",
  "claim_id": "C042",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C042",
    "value": "The conditional canary may expand only after adequate evidence.",
    "scope": "Expansion restriction on the canary proposed if regression and reversal reproduce; evidence adequacy is not defined.",
    "provenance": {
      "refs": [
        {
          "source_id": "P026",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies both the initiating condition and the restriction on expansion."
    }
  },
  "signal_basis": {
    "component_id": "C042_SIGNAL",
    "value": "Reproduction of the regression and its reversal permits a bounded overnight canary with predefined tail-rate, failure and resource stop thresholds. Expansion requires adequate evidence; otherwise the canary halts or rolls back.",
    "scope": "A compatible revert or fix tested through a monitored canary; localization alone establishes association under tested conditions and does not establish deployment safety.",
    "provenance": {
      "refs": [
        {
          "source_id": "P026",
          "role": "SUPPORT"
        },
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the conditional canary procedure, expansion gate and limits on what localization establishes."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C042_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as an explicit procedural restriction, without an unresolved empirical bridge."
    }
  },
  "rationale": "The claim states a necessary condition for expansion, not that the observed localization or reproduced reversal supplies sufficient evidence to expand. The bounded, monitored procedure licenses that restriction within its stated limits.",
  "uncertainty": "Evidence adequacy is unspecified, so this judgment does not establish that any particular canary has met the expansion gate.",
  "anomalies": []
}
